  "message": $('tf-message').isExecuted ? $('tf-message').first().json.message.message.text : $('tf-message').first().json.message.message.text || $('tf-message').item.json.message.message.attachment.description || $json.message,
  "sent_at": $('tf-message').first().json.message.messageId
             ? Math.floor($('tf-message').first().json.message.messageId / 1000)
             : new Date().getTime(),
  "first_name": $('sorento-sub-respond-findcontact-respond').first().json.firstName,
  "last_name": $('sorento-sub-respond-findcontact-respond').first().json.lastName,
  "reply_to_message_id": $('tf-message').first().json.message.replyTo?.id ?? null,
  "reply_to_message": $('tf-message').first().json.message.replyTo?.message?.text ?? null,
  "type": "incoming",
  "message_id": `${$('tf-message').first().json.message.messageId}`,
  "turn_id": `${$execution.id}`,
  "state_trace": (() => {
    const RS = ['last_result_set', 'referenced_result_set', 'dym_candidates'];
    const trim = (o) => {
      if (o === null || o === undefined) return null;
      if (typeof o !== 'object') return o;
      let c;
      try { c = JSON.parse(JSON.stringify(o)); } catch (e) { return null; }
      for (const k of RS) {
        const v = c[k];
        if (Array.isArray(v)) {
          const f = v.length ? v[0] : null;
          c[k] = {
            n: v.length,
            first: f ? (f.label ?? f.code ?? f.canonical_code ?? f.raw ?? f.uuid ?? null) : null
          };
        }
      }
      return c;
    };
    let before = null, parser_raw = null, parser_applied = null, after = null;
    try {
      if ($("get-session-vars").isExecuted) {
        before = $("get-session-vars").first().json.session_vars.variables ?? null;
      }
    } catch (e) { before = null; }
    try {
      if ($("Call 'sub-query-reformulator'").isExecuted) {
        const p = $("Call 'sub-query-reformulator'").first().json;
        parser_applied = p.output ?? null;
        parser_raw     = p._parser_raw ?? null;
      }
    } catch (e) { parser_applied = null; parser_raw = null; }
    try {
      if ($("compile-current-state").isExecuted) {
        after = $("compile-current-state").first().json.variables ?? null;
      }
    } catch (e) { after = null; }
    return {
      v: 1,
      before:         trim(before),
      parser_raw:     trim(parser_raw),
      parser_applied: trim(parser_applied),
      after:          trim(after)
    };
  })()
}) }}

