    const _g = $('disallowed-entity-gate').first().json ?? {};
    return new Set((_g.resolutions ?? [])
      .filter(x => x && x.resolved === true && x.resolved_by === 'document-class-narrowing')
      .map(x => String(x.token ?? '').trim().toLowerCase())
      .filter(Boolean));
