value.semantic_input:
={{ (() => {
  const parser = $("Call 'sub-query-reformulator'").first().json.output;
  const aggExecuted = $('Aggregate').isExecuted;
  const accessLevels = aggExecuted
    ? $('Aggregate').first().json.name.sort().filter(a => (parser.access_levels || []).includes(a))
    : (parser.access_levels || []);
  return {
    message_type:      parser.message_type      ?? null,
    intent_hint:       parser.intent_hint       ?? null,
    domain_hint:       parser.domain_hint       ?? null,
    user_goal:         parser.user_goal         ?? null,
    access_levels:     accessLevels,
    contact_id:        $("sorento-sub-respond-findcontact-respond").first().json.id.toString() ?? null,
    space_id:          "364817",
    date_mode:         parser.date_mode         ?? null,
    date_filter_start: parser.date_filter_start ?? null,
    date_filter_end:   parser.date_filter_end   ?? null,
    is_active:         parser.is_active         ?? null,
    order_status:      parser.order_status      ?? null,
    requested_attributes: parser.requested_attributes ?? [],
  };
})() }}

parameters.jsCode:
const gate  = $('disallowed-entity-gate').first().json ?? {};
const probe = (() => { try { return $('probe-incoming').first().json ?? {}; } catch (e) { return {}; } })();

// codes WITH incoming from probe answers (crm_incoming_stock_list returns a row per
// product that HAS incoming; title / "Product Code" field = the code). Absent = none.
const norm = s => String(s ?? '').trim().toLowerCase();
const answers = Array.isArray(probe.answers) ? probe.answers
              : (Array.isArray(probe.items) ? probe.items : []);
const hasIncoming = new Set();
for (const a of answers) {
  let code = a && a.title;
  if (!code && a && Array.isArray(a.fields)) {
    const f = a.fields.find(x => /product\s*code/i.test(x && x.label));
    code = f && f.value;
  }
  if (code) hasIncoming.add(norm(code));
}

// annotate the EXISTING numbered picker text — same lines, same order, same numbering.
// display-only: compatible_entities (the roster used for the next-turn pick) is untouched.
const src = String(gate.gate_clarification || '');
const annotated = src.split('\n').map(line => {
  const m = line.match(/^\s*\d+\.\s+(.+?)\s*$/);
  if (!m) return line;                                   // header / non-item line
  const status = hasIncoming.has(norm(m[1])) ? ' — has incoming' : ' — no incoming';
  return line + status;
}).join('\n');

let msg = annotated;
if (hasIncoming.size === 0) msg += '\n\nNone of these have incoming stock right now.';

const out = gate;                                        // clean roster item, order intact
out.escalate_message = msg;
out.is_clarification = false;                            // parity with not-found require_specific branch
return out;

// sibling-transform (PHASE 1) — strict-prefix/boundary family filter over the uncapped
// products-list read. Emits ONE item carrying the sibling family array so sibling-probe
// runs exactly once (batched). PHASE-2 SEAM: union across multiple base codes builds here.
const norm = s => String(s ?? '').trim().toLowerCase();
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const gate = (() => { try { return $('disallowed-entity-gate').first().json ?? {}; } catch (e) { return {}; } })();
const compat = Array.isArray(gate.compatible_entities) ? gate.compatible_entities : [];
// PHASE 1: single base code = the first exactly-resolved product (non-uuid code).
const baseEntity = compat.find(e => e && String(e.entity_type).toLowerCase() === 'product'
  && e.code && !UUID_RE.test(String(e.code)));
const baseCode = baseEntity ? String(baseEntity.code) : '';
const baseN = norm(baseCode);

// products-list response (defensive across container shapes)
const resp = $input.first().json ?? {};
const rows = Array.isArray(resp) ? resp
  : (Array.isArray(resp.data) ? resp.data
  : (Array.isArray(resp.items) ? resp.items
  : (Array.isArray(resp.products) ? resp.products
  : (Array.isArray(resp.results) ? resp.results
  : (resp.data && Array.isArray(resp.data.items) ? resp.data.items : [])))));

// strict family: code === base, OR startsWith(base) with a boundary delimiter or EOS
const BOUNDARY = new Set(['-', '/', ' ']);
const inFamily = (code) => {
  const c = norm(code);
  if (!c || !baseN) return false;
  if (c === baseN) return true;
  if (!c.startsWith(baseN)) return false;
  const next = c.charAt(baseN.length);
  return next === '' || BOUNDARY.has(next);
};

const seen = new Set();
const siblings = [];
for (const row of rows) {
  const code = row && (row.product_code ?? row.code);
  const uuid = row && (row.id ?? row.uuid ?? null);
  if (!code || !inFamily(code)) continue;
  const key = norm(code);
  if (seen.has(key)) continue;
  seen.add(key);
  siblings.push({ uuid: uuid || null, entity_type: 'product', code: String(code) });
}

return [{ json: { siblings, base_codes: baseCode ? [baseCode] : [], sibling_count: siblings.length } }];

