parameters.jsCode:
// Relay the ideation turn result (real http in prod, mock in clone via ideate-turn)
// into the shared compile->send->save path. Reuse (Rev-3.1): n8n stays the central
// session_vars writer; hand compile the returned ideation pointer to persist.
const r = $('ideate-turn').first().json || {};
let response = r.reply_text || '';
// The REAL endpoint already embeds the deep link inside reply_text on complete
// ("Track it here: <link>"); appending r.link unconditionally rendered it twice.
// Only append when the reply doesn't already carry it (the mock doesn't).
if (r.status === 'complete' && r.link && !response.includes(r.link)) response += `\n\n${r.link}`;
// SHAPE TOLERANCE: the mock returns the n8n-native nested blob
// ({ session_vars: { variables: { ideation } } }), but the REAL turn endpoint keys
// `ideation` at the TOP level of session_vars (ideation_turn_service reads/writes
// session_vars['ideation'] flat). Reading only the nested path silently yielded null
// against the real endpoint, so the pointer never persisted. Accept BOTH.
const sv = r.session_vars || {};
const ideation = (sv.ideation !== undefined ? sv.ideation : ((sv.variables && sv.variables.ideation) || null)) || null;
return [{ json: { response, manualResponse: true, includeResponse: true, ideation, ideate_status: r.status || 'error' } }];

// Fail-closed MOCK of the ideation turn endpoint — clone/test path only (is_test via
// test_run_id). Mirrors the real endpoint response shape so build-ideate-reply +
// compile-current-state behave identically. Inject message.mock_ideate_response to
// exercise review/complete/duplicate statuses; else default a 'collecting' turn.
const inj = (() => { try { return $('redis-pop-main-message-list').first().json.message.mock_ideate_response || null; } catch (e) { return null; } })();
if (inj) return [{ json: inj }];
return [{ json: {
  status: 'collecting',
  reply_text: "Here's what I've got so far:\n- Problem statement: (mock)\n\nStill need: Impact, Department.",
  link: null,
  session_vars: { variables: { ideation: { draft_id: 'mock-draft-0001', status: 'collecting', missing: ['impact','department'], updated_at: '2026-07-20T00:00:00Z' } } }
} }];

// STT (DC-5): fold the Whisper transcript back into the QUEUE ITEM, upstream of
// 'tf-message'. Every downstream node resolves the turn text via $('tf-message') BY NODE
// NAME, so a transcript injected further down is invisible to them — patching here makes a
// voice turn indistinguishable from a typed one, with zero downstream edits.
//
// Shape (grounded, exec 9240705):
//   redis-pop .json.message                 = the queue item (A)
//   A.message                               = B  <- tf-message returns THIS
//   B.message.message                       = E  { text, type, attachment }
const src = $('redis-pop-main-message-list').first().json;
const item = JSON.parse(JSON.stringify(src));

// real lane -> Whisper's { text }; mock lane -> the injected mock_transcript
const transcript = ($json && $json.text)
  ? String($json.text)
  : String(item.message.mock_transcript || '');

const E = item.message.message.message.message;
E.attachment = E.attachment || {};
// Keep the original url for sorento's media lookback / debugging, then neutralise the local
// type so the EXISTING downstream 'if-message-is-audio' gate takes its normal FALSE branch
// (its TRUE output is dead-empty). Sorento fetches the audio from Respond itself, so nothing
// is lost by flipping the type here.
E.attachment.source_url = E.attachment.url || null;
E.attachment.type = 'text';
E.text = transcript;
E.type = 'text';

item.message._transcribed = true;
item.message._transcript = transcript;

return [{ json: item }];

// Console-attached voice note: the queue item is JSON-only (redis), so zz-chat carried the
// audio as base64 in `audio_b64`. Decode it back into a binary property so the SAME
// 'whisper-transcribe' node handles it — the console lane and the production
// fetch-from-Respond lane converge on one transcriber.
// n8n binary wants the base64 payload in `.data`, which is exactly what zz-chat forwarded.
const src = $('redis-pop-main-message-list').first().json.message;
const mime = src.audio_mime || 'audio/webm';
const name = src.audio_name || ('voice.' + (mime.split('/')[1] || 'webm'));
return [{
  json: {},
  binary: { data: { data: src.audio_b64, mimeType: mime, fileName: name } },
}];

// ── crossdomain-zeroset ─────────────────────────────────────────────────
// SINGLE SOURCE OF TRUTH for "asked but returned nothing" (plan cross-domain-stock-incoming §3 node 1).
// Passes the validator item through UNTOUCHED except for one namespaced key `_xd`, so If6 and the
// entire downstream miss path see exactly what they see today.
const pass = $input.first().json;
const out = { ...pass };
const OFF = (why) => { out._xd = { active: false, why }; return [{ json: out }]; };

const qfNode = $("Call 'sub-query-reformulator'");
const qf = (qfNode.isExecuted ? (qfNode.first().json.output || {}) : {});
const dh = qf.domain_hint;
if (dh !== 'inventory' && dh !== 'incoming') return OFF('domain');
if (qf.message_type !== 'business_query') return OFF('message_type');

const norm = s => String(s).trim().toUpperCase();
const OTHER_TOOL = dh === 'incoming' ? 'crm_inventory_stock_balance_list' : 'crm_incoming_stock_list';
const TEAM       = dh === 'incoming' ? 'purchasing' : 'warehouse';

// ── returned set. compile-current-state's getResultObj() prefers central-exchange, which does not
// exist yet at this point in the chain — so read validator and REPLICATE central-exchange's unwrap.
// Parity is proven by the shadow gate (plan §8 2b), never assumed.
let env = pass;
if (env && env.output && typeof env.output === 'object') env = env.output;
const items = Array.isArray(env.answers) ? env.answers : (Array.isArray(env.items) ? env.items : []);
const fieldVal = (it, label) => {
  const f = ((it && it.fields) || []).find(x => String((x && x.label) || '').trim().toLowerCase() === label);
  return f ? f.value : null;
};
const returnedCodes = new Set();
for (const it of items) {
  const v = fieldVal(it, 'product code');
  if (v != null && String(v).trim() !== '' && String(v).trim() !== '—') returnedCodes.add(norm(v));
}

// ── requested set — rule lifted from live #3 (dym-zerostock-itemize): TYPED-exact U DYM-PICKED.
// NOT compatible_entities: that set drops match_tier and carries resolver-expanded siblings the
// customer never typed.
const _rz = (() => { try { return $('resolve-entity').first().json || {}; } catch (e) { return {}; } })();
const _isProd = m => m && String(m.entity_type).toLowerCase() === 'product';
const requested = [];
const _seen = new Set();
const _add = (code, uuid, strict) => {
  if (code == null || code === '') return;
  const n = norm(code); if (!n) return;
  if (_seen.has(n)) {
    if (strict) { const ex = requested.find(x => x._n === n); if (ex) ex.strict = true; }
    return;
  }
  _seen.add(n);
  requested.push({ _n: n, code, uuid: uuid || null, strict: !!strict });
};
const _or = Array.isArray(_rz.resolutions) ? _rz.resolutions : null;
const _uuidByCode = new Map();
for (const r of (_or || [])) {
  for (const m of ((r && r.matches) || [])) {
    if (_isProd(m) && m.canonical_code && !_uuidByCode.has(norm(m.canonical_code))) _uuidByCode.set(norm(m.canonical_code), m.uuid);
  }
}
if (_or) {
  for (const r of _or) {
    const prods = ((r && r.matches) || []).filter(_isProd);
    if (!prods.length) continue;
    const exacts = prods.filter(m => m.match_tier === 'exact');
    if (exacts.length) { for (const m of exacts) if (m.canonical_code) _add(m.canonical_code, m.uuid, false); }
    else if (prods.length === 1 && prods[0].canonical_code) _add(prods[0].canonical_code, prods[0].uuid, false);
  }
} else {
  const _tok = new Set((Array.isArray(_rz.tokens) ? _rz.tokens : []).map(norm));
  const _int = Array.isArray(_rz.intersection) ? _rz.intersection
             : (_rz.by_entity_type ? Object.values(_rz.by_entity_type).flat() : []);
  for (const m of _int) if (_isProd(m) && m.canonical_code && _tok.has(norm(m.canonical_code))) _add(m.canonical_code, m.uuid, false);
}
// DYM-PICKED (strict) — prior cumulative picks + this turn's pick
try {
  const s = $('get-session-vars').first().json;
  const v = (s && s.session_vars && s.session_vars.variables) || (s && s.variables) || null;
  const prev = (v && v.dym_offer && Array.isArray(v.dym_offer.picked)) ? v.dym_offer.picked : [];
  for (const c of prev) _add(c, _uuidByCode.get(norm(c)), true);
} catch (e) {}
if (qf.dym_offer_pick_code) _add(qf.dym_offer_pick_code, _uuidByCode.get(norm(qf.dym_offer_pick_code)), true);

// ── missing: TYPED -> prefix-family satisfaction; PICKED -> strict exact.
// NOTE the deliberate divergence from live #3: it bails when returnedCodes is empty; we must NOT,
// because that is exactly the total-miss case this feature exists for.
const missing = [];
for (const rq of requested) {
  let ok = false;
  if (rq.strict) ok = returnedCodes.has(rq._n);
  else for (const rc of returnedCodes) if (rc === rq._n || rc.startsWith(rq._n)) { ok = true; break; }
  if (!ok) missing.push({ code: rq.code, uuid: rq.uuid, _n: rq._n, entity_type: 'product' });
}
const probeable = missing.filter(m => m.uuid);

out._xd = {
  active: probeable.length > 0,
  origin_domain: dh,
  other_tool: OTHER_TOOL,
  team: TEAM,
  requested: requested.map(r => r.code),
  returned_codes: [...returnedCodes],
  missing,
  probe_entities: probeable.map(m => ({ uuid: m.uuid, entity_type: 'product', code: m.code })),
};
return [{ json: out }];

