// ── Domain ↔ Entity-Type Gate (compatibility + required-type) ──────────────
const parser   = $('Call \'sub-query-reformulator\'').first().json.output ?? {};
const domain   = parser.domain_hint ?? null;
const resolver = $('resolve-entity').first().json ?? {};

const ALLOWED = {
  master_products:    ['product', 'category', 'brand'],
  product_attachment: ['product', 'attachment', 'attachment_type', 'category', 'brand', 'certificate'],
  promotion:          ['product', 'promotion', 'category', 'brand'],
  inventory:          ['product', 'category', 'brand'],
  order:              ['order', 'customer_order', 'transporter', 'customer', 'product'],
  incoming:           ['product', 'inbound_shipment', 'category', 'brand'],
  forms:              ['form'],
  portal_link:        [],
};
const ALLOWS_EMPTY = {
  promotion: true, incoming: true, forms: true, portal_link: true,
  master_products: false, product_attachment: false, inventory: false, order: false,
};

// Domains that need a SPECIFIC type present to be scopable (beyond compatibility).
const REQUIRED_TYPES = { product_attachment: ['attachment_type'] };
const TYPE_PROMPT = {
  attachment_type: 'product image, technical drawing, 3D model, or certificate',
};

// Flatten + de-dupe resolver matches.
const flat = [
  ...(resolver.resolutions ?? []).flatMap(r => r.matches ?? []),
  ...(resolver.intersection ?? []),
  ...Object.values(resolver.by_entity_type ?? {}).flat(),
];
const byUuid = {};
for (const m of flat) if (m && m.uuid) byUuid[m.uuid] = { uuid: m.uuid, entity_type: m.entity_type, code: m.canonical_code };
const entities = Object.values(byUuid);

const allowed = ALLOWED[domain] ?? null;
let gate_passed = true, gate_reason = 'ok', gate_clarification = '';
let compatible_entities = entities;

if (allowed === null) {
  gate_reason = `domain '${domain}' not in matrix; passing through unscoped`;
} else {
  compatible_entities = entities.filter(e => allowed.includes(e.entity_type));

  if (entities.length === 0) {
    gate_passed = ALLOWS_EMPTY[domain] === true;
    gate_reason = gate_passed ? `no entities; '${domain}' permits broad query`
                              : `no entities and '${domain}' requires a scoping entity`;
  } else if (compatible_entities.length === 0) {
    const got = [...new Set(entities.map(e => e.entity_type))].join(', ');
    gate_passed = false;
    gate_reason = `types [${got}] incompatible with '${domain}'`;
  }
}

// Required-type check (only if still passing). Look in resolver output AND raw parser hints,
// since an attachment_type may be a filter the parser carried, not a UUID-resolved record.
if (gate_passed && Array.isArray(REQUIRED_TYPES[domain])) {
  const haveTypes = new Set([
    ...entities.map(e => e.entity_type),
    ...(parser.entities ?? []).map(e => e.hint),
  ]);
  const missing = REQUIRED_TYPES[domain].filter(t => !haveTypes.has(t));
  if (missing.length > 0) {
    gate_passed = false;
    gate_reason = `'${domain}' requires [${missing.join(', ')}] but none resolved`;

    const subject = (parser.entities ?? []).find(e => e.hint === 'product')?.raw || 'this product';
    gate_clarification = missing.map(t =>
      t === 'attachment_type'
        ? `Please specify which type of attachment you need for ${subject} — e.g. ${TYPE_PROMPT.attachment_type}.`
        : `Please specify the ${t}.`
    ).join(' ');
  }
}

// ── B1 attachment-subject-gate ─────────────────────────────────────────
// The named subject product MISSED. A carried certificate / attachment_type must not be
// allowed to scope the lookup on its own: certificate_ids alone satisfies the tool's narrowing
// tuple (server.py:40, OR semantics) and returns every product carrying that certificate.
// Observed: exec 11509873, 26 unrelated products + a PDF. Dead-end to not-found so the
// did-you-mean the customer actually needs is what gets rendered.
// Predicate is resolver-derived (unresolved_tokens ∩ parser product raws) on purpose — NOT
// `current_message`, which is a known-corrupted signal (plan §5 B4).
if (gate_passed && domain === 'product_attachment') {
  const _n = s => String(s ?? '').trim().toLowerCase();
  const _unresolved = (resolver.unresolved_tokens ?? []).map(_n);
  const _productRaws = new Set((parser.entities ?? [])
    .filter(e => String(e.hint || '').toLowerCase() === 'product')
    .map(e => _n(e.raw)));
  const _missedSubject = _unresolved.some(t => _productRaws.has(t));
  const _haveProduct   = compatible_entities.some(e => e.entity_type === 'product');
  if (_missedSubject && !_haveProduct) {
    gate_passed = false;
    gate_reason = `'product_attachment' subject product did not resolve; refusing to scope on carried entities`;
  }
}

// ── AMBIGUITY → REQUIRE SPECIFIC SELECTION ──────────────────────────────
// Domains where an ambiguous token must be disambiguated by the user before we
// can scope a lookup. (promotion already short-circuits below; this generalizes it.)
const REQUIRE_SPECIFIC_DOMAINS = new Set(['incoming', 'product_attachment']);
let require_specific = false;
let specific_options = [];
let exact_entities = [];   // tokens resolved by a single compatible exact match

if (REQUIRE_SPECIFIC_DOMAINS.has(domain)) {
  const allowedTypes = ALLOWED[domain] ?? null;
  const norm = s => String(s || '').toLowerCase().trim();
  const tokens = resolver.tokens ?? [];
  const typedTokens = new Set(tokens.map(norm));

  const isCompatible = m => allowedTypes === null || allowedTypes.includes(m.entity_type);
  const isProd = m => String(m.entity_type).toLowerCase() === 'product';

  // OR-mode: per-token resolutions[]. AND-mode: flat intersection[] (no token, no usable tier).
  const orResolutions = Array.isArray(resolver.resolutions) ? resolver.resolutions : null;
  const andMatches    = Array.isArray(resolver.intersection) ? resolver.intersection
                      : (resolver.by_entity_type ? Object.values(resolver.by_entity_type).flat() : null);

  if (orResolutions) {
    // ── OR-MODE ──
    // FIX D: the disambiguation choose-list is PRODUCT-ONLY. Non-product matches
    // (attachment_type, etc.) are resolved straight through and NEVER offered as a
    // choice. Only genuine multi-product-no-exact tokens prompt the user.
    const stillAmbiguous = [];
    for (const r of orResolutions) {
      const matches = (r.matches ?? []).filter(isCompatible);
      if (matches.length === 0) continue;

      const products    = matches.filter(isProd);
      const nonProducts = matches.filter(m => !isProd(m));

      // resolve non-product matches (attachment_type, etc.) — never a choose-list option
      if (nonProducts.length > 0) {
        const npExact = nonProducts.filter(m => m.match_tier === 'exact');
        const pick = npExact.length === 1 ? npExact[0] : nonProducts[0];
        exact_entities.push({ uuid: pick.uuid, entity_type: pick.entity_type, code: pick.canonical_code });
      }

      // products: exact-tier wins (user typed a full code; ignore -BL/-150 variants)
      if (products.length > 0) {
        const exacts = products.filter(m => m.match_tier === 'exact');
        if (exacts.length === 1) {
          const m = exacts[0];
          exact_entities.push({ uuid: m.uuid, entity_type: m.entity_type, code: m.canonical_code });
        } else if (products.length === 1) {
          const m = products[0];
          exact_entities.push({ uuid: m.uuid, entity_type: m.entity_type, code: m.canonical_code });
        } else {
          // multiple product matches, no single exact → genuinely ambiguous → prompt
          stillAmbiguous.push({ token: r.token, products });
        }
      }
    }
    if (stillAmbiguous.length > 0) {
      specific_options = stillAmbiguous.map(o => ({
        token: o.token,
        candidates: o.products.map(m => ({
          uuid: m.uuid,
          label: m.canonical_code || m.display?.product_name || m.uuid,
          entity_type: m.entity_type,
        })),
      })).filter(o => o.candidates.length > 0);
    }

  } else if (andMatches) {
    // ── AND-MODE: tier is uninformative; exact = canonical_code EQUALS a typed token ──
    // FIX D: resolve non-product matches straight through; choose-list = products only.
    const compatMatches = andMatches.filter(m => m && isCompatible(m));
    const nonProducts = compatMatches.filter(m => !isProd(m));
    for (const m of nonProducts) {
      exact_entities.push({ uuid: m.uuid, entity_type: m.entity_type, code: m.canonical_code });
    }
    const products = compatMatches.filter(isProd);
    const prodExacts = products.filter(m => typedTokens.has(norm(m.canonical_code)));
    if (prodExacts.length === 1) {
      const m = prodExacts[0];
      exact_entities.push({ uuid: m.uuid, entity_type: m.entity_type, code: m.canonical_code });
    } else if (products.length > 1) {
      specific_options = [{
        token: tokens.join(', '),
        candidates: products.map(m => ({
          uuid: m.uuid,
          label: m.canonical_code || m.display?.product_name || m.uuid,
          entity_type: m.entity_type,
        })),
      }];
    } else if (products.length === 1) {
      const m = products[0];
      exact_entities.push({ uuid: m.uuid, entity_type: m.entity_type, code: m.canonical_code });
    }
  }

  // ── shared: if we built options, require the user to pick ──
  if (specific_options.length > 0) {
  const norm = s => String(s || '').toLowerCase().trim();
  const tokens = (resolver.tokens ?? []).map(norm).filter(Boolean);

  // keep only candidates whose CODE relates to a typed token (drop description-only matches)
  if (tokens.length > 0) {
    specific_options = specific_options.map(o => ({
      ...o,
      candidates: o.candidates.filter(c => {
        const code = norm(c.code || c.canonical_code || c.label);
        // candidate's code contains a typed token, OR a typed token contains the code
        return tokens.some(t => code.includes(t) || t.includes(code));
      }),
    })).filter(o => o.candidates.length > 0);
  }
}

// FIX A: drop candidates already covered by an exact code-resolution (descriptor noise),
// then drop any token group left empty. A descriptor token whose matches are all the same
// products we already resolved exactly must NOT manufacture false ambiguity.
if (specific_options.length > 0 && exact_entities.length > 0) {
  const exactUuids = new Set(exact_entities.map(e => e.uuid));
  specific_options = specific_options
    .map(o => ({ ...o, candidates: o.candidates.filter(c => !exactUuids.has(c.uuid)) }))
    .filter(o => o.candidates.length > 0);
}

if (specific_options.length > 0) {
  require_specific = true;
  gate_passed = false;
  gate_reason = `'${domain}' ambiguous (no single exact match); user must pick`;
  const flatLabels = specific_options.flatMap(o => o.candidates.map(c => c.label));
  const numbered = flatLabels.map((l, i) => `${i + 1}. ${l}`).join('\n');
  gate_clarification =
    `${domain} search needs to be more specific. Multiple matches found — please choose:\n${numbered}`;
}

  // FIX A: when prompting, the selectable set comes from the token-filtered, exact-deduped
  // specific_options — NOT from the unfiltered `entities` union. gate_clarification was already
  // rendered from specific_options above; do NOT re-derive it here.
  if (require_specific) {
    const optUuids = new Set(specific_options.flatMap(o => o.candidates.map(c => c.uuid)));
    compatible_entities = entities.filter(e => optUuids.has(e.uuid));
  } else if (exact_entities.length > 0) {
    // not prompting → pass the cleanly-resolved entities through as a SET
    compatible_entities = exact_entities;
  }
}

// ── document-class precision (container-status S1) ──────────────────────
// The CRM resolver answers an attachment miss with a word-tier fallback over
// attachment_type: "container status list" returns Packing List (word:list),
// Stock_List (word:list) AND container_status (word:status). All three reach
// attachment_type_id, so a contact GRANTED container status is handed three
// document types when they asked for one. (Measured: exec 11661198.)
//
// The parser already named the class it meant — an `attachment` entity carries
// canonical_code "container status". Use it to pick.
//
// FAIL-OPEN by design: if the parser named nothing, or nothing matches, keep the
// full set. Over-broad is today's behaviour; a wrong narrowing would silently
// answer about the wrong document.
const _dcNorm = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const _dcWanted = new Set(
  (parser.entities ?? [])
    .filter(e => ['attachment', 'attachment_type'].includes(String(e.hint || '').toLowerCase()))
    .map(e => _dcNorm(e.canonical_code))
    .filter(Boolean)
);
let _dcSoleUuid = null;   // set when narrowing lands on exactly ONE document class
if (_dcWanted.size > 0) {
  const _dcTypeMatches = compatible_entities.filter(e => e.entity_type === 'attachment_type');
  if (_dcTypeMatches.length > 1) {
    // `code` is the slug ("container_status"); display.type_name is the human label
    // ("Container Status"). Either may carry the class, so check both — Packing List
    // and Stock_List have code null and only a type_name.
    const _dcNameByUuid = {};
    for (const m of flat) if (m && m.uuid) _dcNameByUuid[m.uuid] = m.display && m.display.type_name;
    const _dcKeep = _dcTypeMatches.filter(e =>
      _dcWanted.has(_dcNorm(e.code)) || _dcWanted.has(_dcNorm(_dcNameByUuid[e.uuid])));
    if (_dcKeep.length > 0) {
      const _dcKeepUuids = new Set(_dcKeep.map(e => e.uuid));
      compatible_entities = compatible_entities.filter(
        e => e.entity_type !== 'attachment_type' || _dcKeepUuids.has(e.uuid));
      gate_reason += `; document-class narrowed to [${_dcKeep.map(e => e.code || _dcNameByUuid[e.uuid]).join(', ')}]`;
      if (_dcKeep.length === 1) _dcSoleUuid = _dcKeep[0].uuid;
    }
  }
}

const out = $input.first().json;

// ── record the narrowing in `resolutions`, not just in `compatible_entities` ──────────
// Narrowing above fixes WHICH document we ask the CRM for, but the resolver's own verdict for
// the token is still {resolved:false, ambiguous:true} — and dym-transform picks its did-you-mean
// candidates straight off `resolutions` (dym-transform.js:155, `res.resolved !== true`). Left
// alone the customer gets BOTH the file and "Couldn't find 'container status list' — did you
// mean Packing List, Stock_List, container_status" in one message, which reads as broken even
// though the answer above it is correct. Measured on the clone after the param fix.
//
// Only claim resolution when the narrowing was UNAMBIGUOUS (exactly one class survived) AND this
// token's own matches actually contain that uuid — otherwise a second, genuinely-missed token in
// the same turn would be silently marked resolved and lose its did-you-mean.
if (_dcSoleUuid && Array.isArray(out.resolutions)) {
  for (const res of out.resolutions) {
    if (!res || res.resolved === true) continue;
    const ms = Array.isArray(res.matches) ? res.matches : [];
    const hit = ms.find(m => m && m.uuid === _dcSoleUuid);
    if (!hit) continue;
    res.resolved  = true;
    res.ambiguous = false;
    res.matches   = [hit];            // the class we actually asked for, not the word-tier spray
    res.resolved_by = 'document-class-narrowing';
  }
}
out.gate_passed = gate_passed;
out.require_specific = require_specific;
out.gate_reason = gate_reason;
out.gate_clarification = gate_clarification;   // '' when nothing to ask
out.compatible_entities = compatible_entities;
out.gate_debug = { domain, allowed_lookup: ALLOWED[domain], entities_count: entities.length };
return out;

const q    = $('Call \'sub-query-reformulator\'').first().json.output;
const r    = $('resolve-entity').first().json ?? {};
const gate = $('disallowed-entity-gate').first().json ?? {};

const resolvedTypes = r?.by_entity_type ? Object.keys(r.by_entity_type) : [];
const parserHints   = Array.isArray(q?.entities) ? q.entities.map(e => e.hint) : [];
const haveAttachmentType =
  resolvedTypes.includes('attachment_type') || parserHints.includes('attachment_type');

const gatePassed = gate.gate_passed !== false;
const gateReason = gate.gate_reason || '';
const allowedTypes = gate?.gate_debug?.allowed_lookup ?? [];


// readable list: ['product','category','brand'] -> "product, category, or brand"
const humanList = (arr) => {
  const a = arr.filter(Boolean);
  if (a.length === 0) return 'a valid value';
  if (a.length === 1) return a[0];
  return `${a.slice(0, -1).join(', ')}, or ${a[a.length - 1]}`;
};

const missingAttachmentType =
  q.domain_hint === 'product_attachment' && !gatePassed && !haveAttachmentType;
const unresolved = Array.isArray(r?.unresolved_tokens) ? r.unresolved_tokens : [];
const hasUnresolved = unresolved.length > 0;

// needsScope = gate failed for lack of scope AND the user genuinely gave nothing.
// If they gave a token that just didn't resolve, that's a lookup miss, not a scope gap.
const needsScope =
  !gatePassed && !missingAttachmentType && !hasUnresolved &&
  /requires a scoping entity/.test(gateReason);

let escalate_message;
const _statusLabel = (q.domain_hint === 'order' && q.order_status === 'outstanding') ? 'outstanding ' : (q.domain_hint === 'order' && q.order_status === 'delivered') ? 'delivered ' : '';
let is_clarification = false;
// datemiss-summary: expose the resolved-entity bullets (• customer: … / • product: …) so
// build-suggest-offer can show them on the date-relaxation offer too, not just escalate_message.
let _found_summary = '';

if (missingAttachmentType) {
  const subject = Array.isArray(q?.entities) ? q.entities.find(e => e.hint === 'product') : null;
  const subjectText = subject ? `${subject.hint} ${subject.raw}` : 'the requested product';
  escalate_message =
    `Please provide the attachment type for ${subjectText} ` +
    `— e.g. product image, technical drawing, or certificate.`;
  is_clarification = true;

} else if (needsScope) {
  escalate_message =
    `A ${q.domain_hint} enquiry can't be answered with a general search — ` +
    `please specify a ${humanList(allowedTypes)} so I can look it up.`;
  is_clarification = true;

} else {
  const tokens     = Array.isArray(r?.tokens) ? r.tokens : [];
  // #11: the access-level phrase ("Mocha Dealer") arrives as a resolver TOKEN, and the
  // `access` suffix below already names it. Without this filter the level prints twice:
  // "Could not find promotion for Mocha Dealer for Mocha Dealer."
  const _accessSet = new Set((Array.isArray(q?.access_levels) ? q.access_levels : [])
    .map(a => String(a ?? '').trim().toLowerCase()).filter(Boolean));
  const _notAccess = t => !_accessSet.has(String(t ?? '').trim().toLowerCase());
  const tokenText  = tokens.filter(_notAccess).join(' ');
  // tokens the user gave that didn't resolve — name them so the miss is concrete
  const unresolvedText = unresolved.filter(_notAccess).join(', ');

  let requested;
  if (resolvedTypes.length && tokenText) {
    requested = `${resolvedTypes.join('/')} ${tokenText}`;
  } else if (tokenText) {
    requested = tokenText;
  } else if (unresolvedText) {
    requested = unresolvedText;
  } else {
    const entities = (Array.isArray(q?.entities) ? q.entities : []).filter(e => _notAccess(e?.raw));
    // #11: '' (not 'the requested item') so the " for ..." segment can be dropped entirely —
    // the access suffix already says what was searched for.
    requested = entities.length
      ? entities.map(e => `${e.hint || 'item'} ${e.raw}`).join(', ')
      : '';
  }

  const dateRange = (q.date_filter_start && q.date_filter_end)
    ? ` from ${q.date_filter_start} to ${q.date_filter_end}` : '';
  // S2 (promotion-picker): the spine now sends the contact's ENTITLEMENT UNION when the
  // customer names no level, while q.access_levels (the parser's view) stays empty — so the
  // old `|| 'End User'` fallback printed a level that was never searched ("no promotion for
  // End User matched these"). Name a level only when the customer actually named one.
  const access = (q.intent_hint === 'check_promotion' && Array.isArray(q.access_levels) && q.access_levels.length)
    ? ` for ${q.access_levels.join(', ')}` : '';
  const team = q.routing?.suggested_team || 'customer_service';
  const active_inactive = q.is_active == true ? " active" : (q.is_active == false ? " inactive" : "")
  const allEnts = Array.isArray(q?.entities) ? q.entities : [];
  const normRaw = s => String(s ?? '').trim().toLowerCase();
  const byRaw = new Map(allEnts.map(e => [normRaw(e.raw), e]));

  // -- resolved-entity breakdown from gate.compatible_entities (authoritative resolved set) --
  // Names what the system actually resolved (entity_type + code), grouped by type, so an
  // entity-not-found miss reads differently from an entity-found-but-no-domain-data miss.
  const _compat = Array.isArray(gate?.compatible_entities) ? gate.compatible_entities : [];
  const _compatUuids = new Set(_compat.map(c => c.uuid));
  // all resolver matches across OR-mode resolutions + AND-mode intersection/by_entity_type
  const _allMatches = [
    ...(Array.isArray(r?.intersection) ? r.intersection : []),
    ...Object.values(r?.by_entity_type ?? {}).flat(),
    ...(Array.isArray(r?.resolutions) ? r.resolutions : []).flatMap(x => x.matches ?? []),
  ];
  // uuid -> friendly display name (promotions have no code — their identifier is the description)
  const _ORDER_TYPES = new Set(['order', 'customer_order', 'order_number']);
  const _dispByUuid = new Map();
  for (const m of _allMatches) {
    if (!m) continue;
    const d = m.display || {};
    let name;
    if (_ORDER_TYPES.has(m.entity_type)) {
      // order-ish: the user identifies by the DO/order NUMBER — show the code, add the customer for context.
      name = m.canonical_code
        ? (d.customer_name ? `${m.canonical_code} (${d.customer_name})` : m.canonical_code)
        : (d.customer_name || '');
    } else {
      // attachment_type shows its type_name (e.g. "Certification"), NOT the long alias description.
      // description stays ahead of canonical_code so promotions (code == uuid) still show their name.
      name = d.product_name || d.customer_name || d.debtor_name || d.type_name || d.description || m.canonical_code || '';
    }
    if (m.uuid && name && !_dispByUuid.has(m.uuid)) _dispByUuid.set(m.uuid, name);
  }
  // tokens that ACTUALLY produced a compatible entity (via_token / resolution token) —
  // these must NOT be listed as "not found" even if the resolver kept them in unresolved_tokens
  // (fallback-tier matches like brand_access_fallback stay in unresolved_tokens yet resolve).
  const _resolvedToks = new Set();
  for (const m of _allMatches) {
    if (m && _compatUuids.has(m.uuid)) {
      if (m.display?.via_token) _resolvedToks.add(normRaw(m.display.via_token));
      if (m.canonical_code)     _resolvedToks.add(normRaw(m.canonical_code));
    }
  }
  for (const res of (Array.isArray(r?.resolutions) ? r.resolutions : [])) {
    if ((res.matches ?? []).some(m => _compatUuids.has(m.uuid))) _resolvedToks.add(normRaw(res.token));
  }
  const _byType = new Map();
  for (const c of _compat) {
    const et = c.entity_type || 'item';
    // prefer the human display (e.g. promotion description) over a raw UUID code
    const label = _dispByUuid.get(c.uuid) || c.code || c.uuid;
    if (!label) continue;
    if (!_byType.has(et)) _byType.set(et, []);
    const arr = _byType.get(et);
    if (!arr.includes(label)) arr.push(label);
  }
  // #12: when the customer typed a code that matches EXACTLY, that code must be the
  // representative. `_compat` order is arbitrary, so codes[0] could name a sibling variant
  // (SRTSH1040-T for a typed SRTSH1040), reading as if we looked up a different product.
  const _tokSet = new Set(tokens.map(t => String(t ?? '').trim().toLowerCase()).filter(Boolean));
  for (const arr of _byType.values()) {
    const i = arr.findIndex(l => _tokSet.has(String(l).trim().toLowerCase()));
    if (i > 0) arr.unshift(arr.splice(i, 1)[0]);
  }
  const _foundLines = [];
  for (const [et, codes] of _byType) {
    // one representative per type + count; true ambiguity is handled by the gate (did-you-mean)
    const extra = codes.length > 1 ? ` (+${codes.length - 1} more)` : '';
    _foundLines.push(`• ${et}: ${codes[0]}${extra}`);
  }
  _found_summary = _foundLines.join('\n');   // datemiss-summary: reused by build-suggest-offer
  // tokens the user gave that resolved to NOTHING (exclude those that resolved via fallback tiers)
  const _notFoundRaw = unresolved.filter(t => !_resolvedToks.has(normRaw(t)));
  const _useBreakdown = _foundLines.length > 0;
  // notFoundRaw override lets a branch fold some unresolved tokens into the searched noun
  // instead of listing them as "couldn't find" (e.g. attachment qualifiers like "SPAN").
  const buildBreakdownMsg = (domainWord, notFoundRaw) => {
    const nf = (notFoundRaw ?? _notFoundRaw).map(t => `"${t}"`);
    const parts = [];
    if (_foundLines.length) parts.push(`Here's what you want:\n${_foundLines.join('\n')}`);
    if (nf.length) parts.push(`Couldn't find: ${nf.join(', ')}.`);
    parts.push(`But no${active_inactive} ${domainWord}${dateRange}${access} matched these. Would you like me to escalate to ${team} team?`);
    return parts.join('\n\n');
  };

  // vague-token clarify: among UNRESOLVED tokens only, map each back to a reformulator
  // entity by raw and read its `confident` flag. ANY confident:false => vague mash, not a
  // clear-but-missing record => CLARIFY (no escalate offer). Default-true: only === false fires.
  const vagueUnresolved = unresolved.filter(t => byRaw.get(normRaw(t))?.confident === false);

  if (vagueUnresolved.length > 0) {
    is_clarification = true;                       // escalate-catalog: is_escalate_offer = !is_clarification = false
    const labels = humanList(allowedTypes);        // ALLOWED[domain] = gate_debug.allowed_lookup
    const captured = vagueUnresolved.join(', ');
    // partial-aware: name what DID resolve (entities not in unresolved), excluding the vague blob(s).
    const unresolvedSet = new Set(unresolved.map(normRaw));
    const resolvedEnts = allEnts.filter(e => e && e.raw && !unresolvedSet.has(normRaw(e.raw)));
    const resolvedSummary = resolvedEnts
      .map(e => `${e.hint || 'item'} ${e.raw}`.trim())
      .filter(Boolean)
      .join(', ');
    if (resolvedSummary) {
      escalate_message =
        `I understood ${resolvedSummary}, but couldn't make out "${captured}" — ` +
        `is that a ${labels}? Please label it, e.g. customer <name>, product <code>.`;
    } else {
      escalate_message =
        `I captured "${captured}" but couldn't tell which part is which. ` +
        `For a ${q.domain_hint} enquiry, please give me a labeled specific — e.g. ${labels}.`;
    }
  } else {
  const require_specific = gate.require_specific
  if (require_specific) {
    escalate_message = gate.gate_clarification
  } else if (q.domain_hint === 'product_attachment') {
    // FIX B: natural, parser-driven phrasing — never leak the 'product_attachment' literal.
    const ents = Array.isArray(q?.entities) ? q.entities : [];
    const productRaws = ents.filter(e => e.hint === 'product').map(e => e.raw).filter(Boolean);
    const attachRaws  = ents.filter(e => e.hint === 'attachment_type').map(e => e.raw).filter(Boolean);
    const attachEnt   = ents.find(e => e.hint === 'attachment_type');
    if (_useBreakdown) {
      // combine the attachment-type qualifiers into ONE searched noun ("SPAN certificate")
      // and fold those qualifiers OUT of the "couldn't find" list (don't double-name them).
      const attachNoun = attachRaws.length ? attachRaws.join(' ') : (attachEnt?.raw || 'attachment');
      const attachSet  = new Set(attachRaws.map(normRaw));
      const nfRaw      = _notFoundRaw.filter(t => !attachSet.has(normRaw(t)));
      escalate_message = buildBreakdownMsg(attachNoun, nfRaw);
    } else {
      const prodText = productRaws.length ? `product ${productRaws.join(' and ')}` : '';
      let subject;
      if (attachEnt?.raw && prodText)      subject = `a ${attachEnt.raw} for ${prodText}`;
      else if (attachEnt?.raw)             subject = `a ${attachEnt.raw}`;
      else if (prodText)                   subject = `attachments for ${prodText}`;
      else                                 subject = requested || 'the requested item';   // fall back to the old token text
      escalate_message =
        `Could not find${active_inactive} ${subject}${dateRange}${access}. ` +
        `Would you like me to escalate to ${team} team?`;
    }
  } else {
    // status-filter-aware: a SPECIFIC order/customer_order resolved (the DO exists) but the
    // delivered/outstanding filter returned nothing => the order isn't a miss, it's just not in
    // that status. Say so, using the resolved match's own status/dates.
    const _orderMatch = _allMatches.find(m => m && _compatUuids.has(m.uuid) && _ORDER_TYPES.has(m.entity_type));
    if (_orderMatch && (q.order_status === 'delivered' || q.order_status === 'outstanding')) {
      const d = _orderMatch.display || {};
      const label = `${_orderMatch.canonical_code}${d.customer_name ? ` (${d.customer_name})` : ''}`;
      if (q.order_status === 'delivered') {
        const eta = d.estimated_delivery_date ? ` (estimated delivery ${d.estimated_delivery_date})` : '';
        const st  = d.status ? ` — current status: ${d.status}` : '';
        escalate_message =
          `Order ${label} hasn't been delivered yet${st}. ` +
          `Would you like me to escalate to ${team} team?`;
      } else {
        escalate_message =
          `Order ${label} has no outstanding items — it looks already delivered or closed. ` +
          `Would you like me to escalate to ${team} team?`;
      }
    } else if (_useBreakdown) {
      escalate_message = buildBreakdownMsg(`${_statusLabel}${q.domain_hint}`);
    } else {
      const _forRequested = requested ? ` for ${requested}` : '';
      escalate_message =
      `Could not find${active_inactive} ${_statusLabel}${q.domain_hint}${_forRequested}${dateRange}${access}. ` +
      `Would you like me to escalate to ${team} team?`;
    }
  }
  }
}

const out = $input.first().json;
out.escalate_message = escalate_message;
out.is_clarification = is_clarification;
out.found_summary = _found_summary;   // datemiss-summary: resolved-entity bullets for the date arm
return out;

const names = Array.isArray($input.first().json.name) ? $input.first().json.name : [];
const q = $('Call \'sub-query-reformulator\'').first().json.output ?? {};
const domain = q.domain_hint || 'this enquiry';

// optional: friendlier labels than the raw domain_hint
const LABELS = {
  promotion: 'promotions',
  master_products: 'product information',
  product_attachment: 'product attachments',
  inventory: 'stock',
  order: 'orders',
  incoming: 'incoming stock',
  forms: 'forms',
  portal_link: 'this request',
};
const domainLabel = LABELS[q.domain_hint] || domain;

let escalate_message;
let is_clarification = false;

if (names.length === 0) {
  escalate_message = `You have no access levels configured to get ${domainLabel}.`;
} else {
  // bullet each option on its own line — easier to read on WhatsApp than comma-joined
  const options = names.map(n => `- ${n}`).join('\n');
  escalate_message =
    `Please specify which access level you'd like to use for ${domainLabel}:`;
  is_clarification = true;
}

const out = $input.first().json;
out.escalate_message = escalate_message;
out.is_clarification = is_clarification;
out.quick_reply = names.join(",")
return out;

// ── ONE tool per turn (tool-loop-removal, 2026-08-03) ───────────────────────────
// Emits EXACTLY ONE item, always. The per-tool splitOut + splitInBatches fan-out
// that used to sit between this node and get-results is deleted, so nothing
// downstream serialises multiple items any more: two items here would run the whole
// get-results → compile → send chain twice, i.e. two WhatsApp messages to one
// customer. `return [{ json: … }]` is a one-element literal, so the arity is
// structural — it does not depend on how many embeddings the tool registry holds.
//
// Selection = highest `similarity`, tiebreak `name` ASC (deterministic for
// golden-master). Explicitly NOT the first array element: sub-get-rag's final Code
// node collapses source_id → name and does `map[name].similarity += …`, so the SQL
// best-first insertion order is not provably the maximum once any tool has two
// source_ids.
const rag = $("Execute 'sub-get-rag'").first().json || {};
const raw_tools = Array.isArray(rag.tools) ? rag.tools : [];

// Tolerant read of the entity gate. The previous body did
// `entities.some(e => e.entity_type === 'product')` and THREW when
// compatible_entities was undefined; that throw is deliberately removed here and
// the value is recorded rather than dropped (the old `hasProduct` was dead code).
let has_product = null;
try {
  const entities = $('disallowed-entity-gate').first().json.compatible_entities;
  has_product = Array.isArray(entities)
    ? entities.some(e => e && e.entity_type === 'product')
    : null;
} catch (e) {
  has_product = null;
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const score = (t) => {
  const n = Number(t && t.similarity);
  return Number.isFinite(n) ? n : -Infinity;
};
const label = (t) => String((t && t.name) ?? '');
const sorted = raw_tools
  .slice()
  .sort((a, b) => cmp(score(b), score(a)) || cmp(label(a), label(b)));

const best = sorted[0];
// 0 tools in → 0 items out. Preserves today's behaviour exactly (the old splitOut
// emitted 0 items on an empty tools[] and the loop body never ran). Pre-existing
// dead-end, backlog in UAC §TL-EMPTY — deliberately NOT turned into a throw here.
if (!best) return [];

return [
  {
    json: {
      ...best,
      _tool_pick: {
        chosen: label(best),
        rejected: sorted.slice(1).map(t => ({ name: label(t), similarity: score(t) })),
        count: raw_tools.length,
        has_product,
      },
    },
  },
];

const m = $('redis-pop-main-message-list').first().json.message;
const fx = (m.fixtures || {}).get_access_types;
if (Array.isArray(fx)) return fx.map(j => ({ json: j }));
return [{ json: fx || {} }];

// ── escalate-catalog ────────────────────────────────
// Single source of truth for escalation/error messages + their behavior flags.
// Each upstream branch sets ONE field `branch_kind`; this node maps it to the
// message + flags that compile-current-state used to derive via a 7-arm ladder.
// Dynamic kinds (not_found, access_choice) pull their message by reference from
// the upstream Code node that computed it.
const qf  = $('Call \'sub-query-reformulator\'').first().json.output;
const out = $input.first().json;
const kind = out.branch_kind;

let response = '';
let manualResponse = false;
let includeResponse = true;
let is_escalate_offer = false;

switch (kind) {
  case 'not_found': {
    // Normal not-found path uses not-found-error-message. The incoming-picker
    // availability branch bypasses it (annotate-incoming-picker computes the same
    // escalate_message/require_specific/is_clarification), so fall back to that node.
    // dym-probe-before-offer (rev 6): PREFER THE ANNOTATED COPY.
    // build-suggest-offer is the annotation authority for the require-specific picker; it
    // SPREADS rather than mutates, so reading not-found-error-message by name here returns
    // the PRE-annotation string and silently discards the suffixes — computed correctly,
    // rendered bare. This is the same by-name landmine the annotate-incoming-picker
    // fallback below was added for; the suffix is NOT recomputed here.
    // Source order: build-suggest-offer (annotated) -> not-found-error-message ->
    // annotate-incoming-picker. Every source carries escalate_message, require_specific and
    // is_clarification on the SAME object, so the flags below stay coherent with the text
    // regardless of which one wins. Fail-open by construction: a missing, unexecuted or
    // malformed preferred source falls through to exactly today's behaviour.
    const _annotated = (() => {
      try {
        const n = $('build-suggest-offer');
        if (!n.isExecuted) return null;
        const j = n.first().json;
        return (j && typeof j.escalate_message === 'string' && j.escalate_message) ? j : null;
      } catch (e) { return null; }
    })();
    const nfNode = $('not-found-error-message');
    const nf = _annotated
            || (nfNode.isExecuted ? nfNode.first().json : $('annotate-incoming-picker').first().json);
    response       = nf.escalate_message;
    manualResponse = !nf.require_specific;
    is_escalate_offer = !nf.is_clarification;   // offer only when it's not a clarification prompt
    break;
  }
  case 'access_choice':
    response       = $('access-level-choice-message').first().json.escalate_message;
    manualResponse = true;
    break;
  case 'demand_qty':
    response       = 'Please specify your demand quantity';
    manualResponse = true;
    break;
  case 'not_supported':
    response       = "Sorry, we don't support direct goods receive & SPO at the moment. You may ask about incoming stock for a specific product or container";
    manualResponse = true;
    break;
  case 'clarify_menu':
    response       = `I see you're ${qf.user_goal}, Let me understand more.\n\nAre you asking about any of these?\n\n- Product (List Price, Dimension)\n- Photos, Technical Specs, Cert\n- Promotion\n- Forms\n- Stock\n- Delivery order\n- Incoming\n- Catalogue, Warranty\n\nI can help with the topics listed above.`;
    manualResponse = true;
    break;
  case 'escalate_offer':
    response       = `I am sorry the provided answer does not meet your requirements. Would you like me to escalate to ${qf.routing.suggested_team} team?`;
    manualResponse = true;
    is_escalate_offer = true;
    break;
  case 'out_of_scope':
    response        = `Informed the user that request is out of scope and will proceed to escalate to the ${qf.routing.suggested_team} team`;
    manualResponse  = true;
    includeResponse = false;
    break;
  case 'escalation_declined':
    response          = 'Escalation declined.';   // FIXED canned reply — no LLM shaping
    manualResponse    = true;
    includeResponse   = true;
    is_escalate_offer = false;                     // → cs-offer-gate FALSE → straight to compile-current-state
    break;
}

out.response          = response;
out.manualResponse    = manualResponse;
out.includeResponse   = includeResponse;
out.is_escalate_offer = is_escalate_offer;
return out;

// ── build-cs-member-offer (Δ3) ──────────────────────────────────
// Runs only when the cs-offer-gate passed (is_escalate_offer + customer_service + order_enquiries).
// Turns the live team-members roster into a numbered escalation offer, and stores the roster as
// cs_last_result_set + selection_context so the NEXT turn's position pick resolves to a member.
// Empty roster → fall back to the catalog's generic offer (round-robin on a bare "yes").
// get-cs-members returns a JSON array; n8n may emit it as one item (json=array) OR split into
// one item per element — handle both, then keep only real members.
let _raw = $('get-cs-members').all().map(i => i.json);
let members = (_raw.length === 1 && Array.isArray(_raw[0])) ? _raw[0] : _raw;
// exclude members with no respond_user_id — respond.io conversation-assign can't reach them
members = (Array.isArray(members) ? members : []).filter(m => m && m.user_id && m.respond_user_id);
const cat = $('escalate-catalog').first().json;
const out = { ...cat };

if (members.length === 0) {
  out.selection_context = null;
  out.member_offer = false;
  out.cs_last_result_set = [];
  return out;
}

const numbered = members.map((m, i) => `${i + 1}. ${m.name}`).join('\n');
// Preserve the not-found preamble from the catalog ("Could not find X for Y. Would you like me to escalate...?")
// then append the member picker — do NOT discard cat.response.
out.response =
  `${cat.response || 'Would you like me to escalate to customer_service team?'}\n\n` +
  `Please choose who to route to (reply with the number):\n${numbered}\n\n` +
  `If you have no preference, just reply 'yes' and we'll assign automatically.`;
out.member_offer = true;
out.selection_context = 'member_offer';
out.cs_last_result_set = members.map((m, i) => ({
  idx: i + 1, label: m.name, uuid: m.user_id, respond_user_id: m.respond_user_id,
}));
out.manualResponse = true;     // member offer is a manual response (skip business-summary overwrite)
out.includeResponse = true;
return out;

// ── build-suggest-offer (D1/D2/D3) ────────
// Sibling downstream of not-found-error-message. ADDITIVE: passes the not-found
// payload through and, when the miss carries CONCRETE candidates, attaches a
// suggestion offer that compile-current-state renders. No candidates → suggest_offer
// stays false and downstream is byte-identical to before this node existed.
// dym-probe-before-offer: on the sibling-gate[1] inbound the payload now arrives via
// dym-transform (gate FALSE) or dym-annotate (gate TRUE). Both PASS THE NOT-FOUND
// PAYLOAD THROUGH and append their own control keys. Strip those keys here so the
// object this node emits is byte-identical to pre-change on every un-annotated path.
// (Deleting appended keys restores the original insertion order too.)
const _DYM_CTRL_KEYS = ['dym_probe_entities', 'dym_candidate_codes', 'dym_excluded_codes',
  'probe_tool', 'probe_noun', 'probe_predicate', 'probe_needed', 'probe_skip_reason',
  'probe_lane', '_dym_probe_input', 'dym_available_codes', 'dym_probe_meta',
  // C3: both emitted UNCONDITIONALLY by dym-transform, which runs on every not-found turn
  // including every non-enabled domain. Omitting them leaked two stray keys into this node's
  // output on most traffic (reviewer F-STRIP). ⚠️ ANY new dym-transform output key must be added
  // here in the same commit that introduces it.
  'dym_capped_codes', 'probe_cap_applied'];
const out  = { ...$input.first().json };
for (const _k of _DYM_CTRL_KEYS) delete out[_k];
const q    = (() => { try { return $('Call \'sub-query-reformulator\'').first().json.output; } catch (e) { return {}; } })();
const r    = (() => { try { return $('resolve-entity').first().json ?? {}; } catch (e) { return {}; } })();
const gate = (() => { try { return $('disallowed-entity-gate').first().json ?? {}; } catch (e) { return {}; } })();

out.suggest_offer = false;

const team = q?.routing?.suggested_team || 'customer_service';
const YES  = 'Yes, escalate';
const NO   = "No, it's okay";
const cap3 = (a) => (Array.isArray(a) ? a.slice(0, 3) : []);
const humanList = (codes) => codes.length === 1
  ? codes[0]
  : `${codes.slice(0, -1).join(', ')}, or ${codes[codes.length - 1]}`;
// dym-candidate-map scoping: a did-you-mean candidate must be an ENTITY-CODE correction, never
// a date-relaxation alternative. isDateLike detects an ISO/day-month-year value so we never build
// (or later match) a dym entry keyed on a date the bot itself invited ("reply with a date").
const isDateLike   = (s) => { const v = String(s ?? '').trim(); return /^\d{4}[-/]\d{1,2}[-/]\d{1,2}$/.test(v) || /^\d{1,2}[-/]\d{1,2}[-/]\d{2,4}$/.test(v); };
const isCodeShaped = (s) => { const v = String(s ?? '').trim(); return v.length > 0 && /[a-z0-9]/i.test(v) && !isDateLike(v); };
// dym-single-use-fix: wrap a candidate list in an offer object carrying identity + lifecycle.
//   id     = this spine execution id (turn-unique) → stamped onto the picked entity as dym_slot,
//            giving output_exchange a STABLE handle that survives raw-overwrite across repeated picks.
//   domain = the reformulator domain_hint at build time → drives the domain-switch supersede rule.
//   ttl/picked seed the lifecycle that compile-current-state advances each turn.
// candidates[] shape is UNCHANGED from the shipped map. Returns null for an empty set (no offer).
const _mkOffer = (cands) => (Array.isArray(cands) && cands.length)
  ? { id: String($execution.id), domain: (q && q.domain_hint) || null, ttl: 3, candidates: cands, picked: [] }
  : null;

// ── D3: incoming sibling-family picker (empty-exact incoming miss) — PHASE 1 ──
// Fires ONLY when sibling-gate routed the not-found through family-fetch →
// sibling-transform → sibling-probe (all isExecuted). Reuses the shipped suggest_offer
// envelope so the pick/escalate round-trip is the already-proven suggest-follow-up path
// (NO reformulator edit). When sibling-probe/-transform did not run (ambiguous incoming
// picker path, or sibling-gate FALSE), D3 is inert and D1/D2 behave byte-identically.
// PHASE-2 SEAM: multi-product family union (family-loop) not built — single base only.
{
  const sibXfRan    = (() => { try { return $('sibling-transform').isExecuted; } catch (e) { return false; } })();
  const sibProbeRan = (() => { try { return $('sibling-probe').isExecuted; } catch (e) { return false; } })();
  const domIncoming = (q && q.domain_hint === 'incoming')
    || (gate && gate.gate_debug && gate.gate_debug.domain === 'incoming');
  if (sibXfRan && sibProbeRan && domIncoming) {
    const normC = s => String(s ?? '').trim().toLowerCase();
    const fam = (() => { try { return $('sibling-transform').first().json.siblings; } catch (e) { return null; } })();
    const probe = (() => { try { return $('sibling-probe').first().json ?? {}; } catch (e) { return {}; } })();
    if (Array.isArray(fam) && fam.length) {
      // codes WITH incoming from probe answers (crm_incoming_stock_list returns a row per
      // product that HAS incoming; title / "Product Code" field = the code). Same machinery
      // as annotate-incoming-picker.
      const answers = Array.isArray(probe.answers) ? probe.answers
                    : (Array.isArray(probe.items) ? probe.items : []);
      const hasInc = new Set();
      for (const a of answers) {
        let c = a && a.title;
        if (!c && a && Array.isArray(a.fields)) {
          const f = a.fields.find(x => /product\s*code/i.test(x && x.label));
          c = f && f.value;
        }
        if (c) hasInc.add(normC(c));
      }
      // dedupe by code; annotate has/no incoming (exact code INCLUDED, annotated too)
      const seenC = new Set();
      const sibs = fam
        .filter(e => e && e.code && !seenC.has(normC(e.code)) && seenC.add(normC(e.code)))
        .map(e => ({ code: String(e.code), uuid: e.uuid || null, has: hasInc.has(normC(e.code)) }));
      // the exactly-resolved product code(s) — family must offer MORE than just these
      const exactCodes = new Set((Array.isArray(gate && gate.compatible_entities) ? gate.compatible_entities : [])
        .filter(e => e && String(e.entity_type).toLowerCase() === 'product' && e.code)
        .map(e => normC(e.code)));
      const extras = sibs.filter(s => !exactCodes.has(normC(s.code)));
      if (extras.length > 0) {
        // ALWAYS a numbered picker whenever ≥1 sibling exists — regardless of has-incoming.
        // (User reversed the earlier anyHasIncoming split: the all-no-incoming family now ALSO
        // shows a numbered list + number-pick invite, not a list-only/escalate-only variant.)
        // SORT: has-incoming first, then code order. NO cap. (Collapses to code-order when none has incoming.)
        sibs.sort((a, b) => (Number(b.has) - Number(a.has)) || String(a.code).localeCompare(String(b.code)));
        const exactList = [...exactCodes].map(c => c.toUpperCase()).join(', ');
        // Numbered list of ALL siblings; number-pick invite active; positional pick armed.
        const numbered = sibs.map((s, i) => `${i + 1}. ${s.code} — ${s.has ? 'has incoming' : 'no incoming'}`).join('\n');
        out.suggest_offer = true;
        out.suggest_selection_context = 'suggest_offer';
        out.suggest_response =
          `No incoming stock (ETA) found for ${exactList}. Related products:\n` +
          `${numbered}\n` +
          `Reply with a number to check its incoming, or reply 'yes' to escalate to ${team} team.`;
        // Uncapped list → NO per-sibling buttons (respond.io button cap); numbers typed.
        // Only Yes/No buttons, comma-stripped so labels don't split.
        out.suggest_quick_reply = [YES, NO].map(s => String(s).replace(/,/g, '')).join(',');
        out.suggest_last_result_set = sibs.map((s, i) => ({
          idx: i + 1, label: s.code, value: s.code, product: s.code, uuid: s.uuid, entity_type: 'product',
        }));
        return out;
      }
      // extras.length === 0 → only the exact code itself; fall through to plain escalate.
    }
  }
}

// ── UUID leak guard (promotion did-you-mean) ────────
// Promotions have no product code: their canonical_code IS the promo uuid, and the
// human name lives in display.description. Rendering canonical_code as the label leaks
// a raw uuid to the customer. isUuid() detects that; humanLabel() prefers a REAL code,
// else the display name; null ⇒ the candidate has no human label and must be dropped.
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const isUuid = (s) => UUID_RE.test(String(s || ''));
const humanLabel = (m) => {
  const c = m && m.canonical_code;
  if (c && !isUuid(c)) return String(c);
  const d = (m && m.display) || {};
  return d.description || d.product_name || d.name || null;
};

const unresolved  = Array.isArray(r?.unresolved_tokens) ? r.unresolved_tokens : [];
const isClar      = out.is_clarification === true;   // preserve vague/scope clarify prompts
const requireSpec = gate?.require_specific === true;  // preserve require-specific prompts
const allowedTypes = Array.isArray(gate?.gate_debug?.allowed_lookup) ? gate.gate_debug.allowed_lookup : null;
const isExact = (m) => String(m?.match_tier || '').toLowerCase() === 'exact';

// Attachment domain → name the actual doc type the user asked for (photo/certificate/
// drawing) instead of a generic word. Falls back to 'document'.
const attachmentNoun = () => {
  if (q?.domain_hint !== 'product_attachment') return null;
  const at = Array.isArray(q?.entities)
    ? q.entities.find(e => String(e.hint || '').toLowerCase() === 'attachment_type') : null;
  return (at && at.raw) ? at.raw : 'document';
};

// ── D1: resolution-miss "did you mean" — PER-TOKEN, GENUINE-MISS ONLY ────────
// Only a token the resolver could not resolve AND that had no exact match drives a
// did-you-mean, using ITS OWN matches/alternatives. Never aggregate candidates across
// tokens (bug: in a multi-item order, a dead SRTUB6503-BL borrowed SRTMFV207-NL from a
// sibling token). An ambiguous token that still had an exact match returned data → not a miss.
function tokenCandidates(res) {
  const acc = [];
  if (Array.isArray(res?.matches)) acc.push(...res.matches);
  if (Array.isArray(res?.alternatives)) acc.push(...res.alternatives);
  const seen = new Set(); const keep = [];
  for (const m of acc) {
    const code = m && m.canonical_code;
    if (!code) continue;
    if (isExact(m)) continue;                                                  // exact would have resolved
    if (allowedTypes && m.entity_type && !allowedTypes.includes(m.entity_type)) continue;
    if (seen.has(code)) continue;
    seen.add(code); keep.push(m);   // API ranks variants-first / by similarity → keep order
  }
  return keep;
}

// Build the list of genuine miss tokens (their own resolution, no exact match).

// ── honour the gate's document-class narrowing (container-status S1) ────────
// `r` above is bound to the RAW resolver node, so a token the GATE resolved still looks
// unresolved here. Measured: "please send me the container status list" returned the correct
// file AND "Couldn't find 'container status list' — did you mean Packing List, Stock_List,
// container_status" in the same message. The answer was right; the message read as broken.
// Deliberately narrow: only tokens the gate stamped `resolved_by === 'document-class-narrowing'`
// are dropped, so this cannot suppress an ordinary miss.
const _gateResolvedTokens = (() => {
  try {
